-- The category the UI names, by priority. Null when no hard rule fired.
create or replace function private.contact_guard_category(p_rules text[])
returns text
language sql
immutable
strict
parallel safe
as $fn$
  select case
    when p_rules && array['phone_mobile', 'phone_run10', 'phone_intl', 'phone_landline', 'phone_digits', 'phone_spread', 'phone_symbols', 'phone_words', 'phone_reversed']::text[] then 'phone'
    when p_rules && array['vpa', 'ifsc', 'bank_account', 'at_id']::text[] then 'payment'
    when p_rules && array['email', 'email_no_tld', 'mail_local_near']::text[] then 'email'
    when p_rules && array['url_scheme', 'url_known', 'url_tld']::text[] then 'link'
    when p_rules && array['handle', 'app_handle', 'id_colon_handle', 'handle_on_app', 'discord_tag', 'skype_live']::text[] then 'handle'
  end;
$fn$;

-- 'reference' when the only phone rule is a bare 10+ digit run (a UTR, PNR or
-- order id, blocked by policy; the copy points to Help), 'date_like' when it is
-- only the every-digit-joined reading. Null otherwise.
create or replace function private.contact_guard_reason(p_rules text[])
returns text
language sql
immutable
strict
parallel safe
as $fn$
  select case
    when private.contact_guard_category(p_rules) is distinct from 'phone' then null
    when (select array_agg(x order by x) from unnest(p_rules) x
          where x = any(array['phone_mobile', 'phone_run10', 'phone_intl', 'phone_landline', 'phone_digits', 'phone_spread', 'phone_symbols', 'phone_words', 'phone_reversed']::text[])) = array['phone_run10']::text[] then 'reference'
    when (select array_agg(x order by x) from unnest(p_rules) x
          where x = any(array['phone_mobile', 'phone_run10', 'phone_intl', 'phone_landline', 'phone_digits', 'phone_spread', 'phone_symbols', 'phone_words', 'phone_reversed']::text[])) = array['phone_digits']::text[] then 'date_like'
  end;
$fn$;

-- A message that is only digit groups (after carrier words and symbols go)
-- returns its digits; any other message returns ''.
create or replace function private.contact_guard_fragment(p_text text)
returns text
language plpgsql
immutable
strict
parallel safe
as $fn$
declare
  v text;
begin
  v := private.cg_copy_t(p_text);
  v := private.cg_copy_d(v);
  v := private.cg_copy_p(v);
  v := regexp_replace(v, '(?<![a-z0-9])[0-9]{1,2}[ ]*(?:digits|digit|ank)(?![a-z])', ' ', 'g');
  v := regexp_replace(v, '(?<![a-z])(?:remaining|continue|vodafone|contact|airtel|bhejta|bhejti|doosra|likhta|likhti|mobile|number|purana|second|teesra|baaki|bacha|dekho|dusra|first|hissa|likho|madam|pehla|pehle|phone|shuru|start|third|aage|abhi|baki|bhai|bhej|bsnl|cont|dekh|didi|haan|hain|half|hoon|idea|karo|last|likh|mera|mere|meri|naya|next|nmbr|note|okay|part|phir|plus|raha|rahi|rest|ruko|save|suno|then|wala|wali|and|aur|bas|end|fir|hai|han|hmm|hun|jio|kar|mam|nbr|new|num|sim|sir|sun|the|yeh|ab|he|hu|is|ji|ka|ki|le|lo|my|no|of|ok|ph|se|vi|ye|h)(?![a-z])', ' ', 'g');
  v := regexp_replace(v, '[.!?]+[ ]*$', '', 'g');
  v := regexp_replace(v, '[^0-9a-z:/%.\u20b9$-]', ' ', 'g');
  v := regexp_replace(v, '[ ][ ]+', ' ', 'g');
  if v !~ '^[ ]?[0-9]{1,10}(?:[ ][0-9]{1,10})*[ ]?$' then
    return '';
  end if;
  v := regexp_replace(v, '[^0-9]', '', 'g');
  if length(v) < 2 then
    return '';
  end if;
  return v;
end;
$fn$;

-- A message with no run of two or more digits: the window steps over it.
create or replace function private.contact_guard_is_chatter(p_text text)
returns boolean
language plpgsql
immutable
strict
parallel safe
as $fn$
declare
  v text;
begin
  v := private.cg_copy_t(p_text);
  v := private.cg_copy_d(v);
  v := private.cg_copy_p(v);
  return v ~ '^[^0-9]*(?:[0-9][^0-9]+)*[0-9]?[^0-9]*$';
end;
$fn$;

-- p_texts is the sender's recent messages oldest first, the new one last.
-- Joins every run of two or more fragments that ends at the new message, in
-- sending order and reversed, and returns the first join that is a mobile.
-- Null when none is: the new message alone never counts here, the hard rules
-- already judged it.
create or replace function private.contact_guard_window(p_texts text[])
returns text
language plpgsql
immutable
strict
parallel safe
as $fn$
declare
  v_n   integer := coalesce(cardinality(p_texts), 0);
  v_fwd text;
  v_rev text;
  v_pay text;
begin
  if v_n < 2 then
    return null;
  end if;
  v_fwd := private.contact_guard_fragment(coalesce(p_texts[v_n], ''));
  if v_fwd = '' then
    return null;
  end if;
  v_rev := v_fwd;
  for i in reverse v_n - 1 .. 1 loop
    v_pay := private.contact_guard_fragment(coalesce(p_texts[i], ''));
    if v_pay = '' then
      -- Chatter (no digit run of two or more) is stepped over; anything else
      -- with digits ends the run.
      exit when not private.contact_guard_is_chatter(coalesce(p_texts[i], ''));
      continue;
    end if;
    v_fwd := v_pay || v_fwd;
    v_rev := v_rev || v_pay;
    exit when length(v_fwd) > 13;
    if v_fwd ~ '^(?:91|0)?[6-9][0-9]{9}$' then
      return v_fwd;
    end if;
    if v_rev ~ '^(?:91|0)?[6-9][0-9]{9}$' then
      return v_rev;
    end if;
  end loop;
  return null;
end;
$fn$;

-- Every working copy, for parity tests and moderation.
create or replace function private.contact_guard_copies(p_text text)
returns jsonb
language plpgsql
immutable
strict
parallel safe
as $fn$
declare
  v_t text;
  v_d text;
  v_p text;
  v_rp text;
  v_pd text;
  v_pw text;
  v_e text;
  v_ec text;
begin
  v_t := private.cg_copy_t(p_text);
  v_d := private.cg_copy_d(v_t);
  v_p := private.cg_copy_p(v_d);
  v_rp := private.cg_copy_rp(v_p);
  v_pd := private.cg_copy_pd(v_d);
  v_pw := private.cg_copy_pw(v_d);
  v_e := private.cg_copy_e(v_t);
  v_ec := private.cg_copy_ec(v_t);
  return jsonb_build_object('t', v_t, 'd', v_d, 'p', v_p, 'rp', v_rp, 'pd', v_pd, 'pw', v_pw, 'e', v_e, 'ec', v_ec);
end;
$fn$;

create or replace function private.contact_guard_spec_version()
returns text
language sql
immutable
parallel safe
as $fn$
  select 'ac38fff8f98f756c5e2390e3c1a15af11c872acde7eeda491e1e94ff777c7e1f'::text;
$fn$;

do $grants$
declare
  v_fn regprocedure;
begin
  for v_fn in
    select p.oid::regprocedure
    from pg_proc p
    where p.pronamespace = 'private'::regnamespace
      and (p.proname like 'cg\_copy\_%' or p.proname like 'contact\_guard\_%')
      and p.proname not in ('contact_guard_gate', 'contact_guard_log', 'contact_guard_mode', 'contact_guard_purge')
  loop
    execute format('revoke all on function %s from public, anon, authenticated', v_fn);
    execute format('grant execute on function %s to service_role', v_fn);
  end loop;
end;
$grants$;
